-- Source: 202610150002_assessment_review_workflow.sql
-- Twenty-question assessments are drafts until explicitly reviewed and published.

alter table public.course_assessments
  add column if not exists revision uuid not null default gen_random_uuid(),
  add column if not exists published_signature text,
  add column if not exists needs_review boolean not null default true,
  add column if not exists reviewed_by text,
  add column if not exists published_at timestamptz;
alter table public.assessment_attempts add column if not exists assessment_revision uuid;
update public.assessment_attempts a set assessment_revision = c.revision
from public.course_assessments c where c.course_id = a.course_id and a.assessment_revision is null;

create table if not exists public.course_assessment_drafts (
  course_id text primary key references public.courses(id) on delete cascade,
  questions jsonb not null,
  source_signature text not null,
  source_snapshot jsonb not null,
  status text not null default 'needs_review' check (status in ('needs_review','stale','published')),
  created_at timestamptz not null default now(),
  draft_hash text generated always as (md5(questions::text)) stored
);
alter table public.course_assessment_drafts enable row level security;
revoke all on public.course_assessment_drafts from public, anon, authenticated;
grant all on public.course_assessment_drafts to service_role;

-- Includes the complete teaching text and curriculum; excludes cosmetic image edits.
create or replace function public.pap_assessment_source(target_course text) returns jsonb
language sql stable security definer set search_path = '' as $$
  select jsonb_build_object(
    'course', jsonb_build_object('id',c.id,'title',c.title,'description',c.description,'overview',c.overview,'outcomes',c.outcomes),
    'modules', coalesce((select jsonb_agg(jsonb_build_object('id',m.id,'title',m.title,'position',m.position,
      'lessons',coalesce((select jsonb_agg(jsonb_build_object('id',l.id,'title',l.title,'description',l.description,'content',l.content,'position',l.position)
        order by l.position,l.id) from public.lessons l where l.course_id=c.id and l.module_id=m.id),'[]'::jsonb))
      order by m.position,m.id) from public.course_modules m where m.course_id=c.id),'[]'::jsonb))
  from public.courses c where c.id=target_course;
$$;
revoke all on function public.pap_assessment_source(text) from public,anon,authenticated;
grant execute on function public.pap_assessment_source(text) to service_role;

create or replace function public.pap_validate_assessment_bank(target_course text, bank jsonb) returns void
language plpgsql security definer set search_path = '' as $$
declare q jsonb; ids text[] := '{}'; prompts text[] := '{}'; normalized text;
begin
  if bank is null or jsonb_typeof(bank)<>'array' then raise exception 'An assessment must contain exactly 20 questions.'; end if;
  if jsonb_array_length(bank)<>20 then raise exception 'An assessment must contain exactly 20 questions.'; end if;
  for q in select value from jsonb_array_elements(bank) loop
    if jsonb_typeof(q)<>'object' or coalesce(q->>'id','') !~ '^[a-zA-Z0-9_-]{1,80}$' or q->>'id'=any(ids)
      or length(btrim(coalesce(q->>'prompt','')))<10 or length(btrim(coalesce(q->>'explanation','')))<10
      or jsonb_typeof(q->'options') is distinct from 'array'
      or jsonb_typeof(q->'correctIndex') is distinct from 'number'
      or coalesce(q->>'correctIndex','') !~ '^[0-3]$' then raise exception 'Each question needs a unique ID, prompt, four options, valid answer, and explanation.'; end if;
    if jsonb_array_length(q->'options')<>4 or exists(select 1 from jsonb_array_elements(q->'options') o where jsonb_typeof(o)<>'string' or length(btrim(o#>>'{}'))=0)
      or (select count(distinct lower(btrim(value))) from jsonb_array_elements_text(q->'options'))<>4 then
      raise exception 'Each question must have four distinct, nonempty options.';
    end if;
    normalized := lower(regexp_replace(q->>'prompt','[^[:alnum:]]','','g'));
    if normalized=any(prompts) then raise exception 'Assessment questions must be distinct.'; end if;
    if not exists(select 1 from public.lessons where course_id=target_course and id=q->>'lessonId') then
      raise exception 'Every question must reference a current lesson in this course.';
    end if;
    ids := array_append(ids,q->>'id'); prompts := array_append(prompts,normalized);
  end loop;
  if (select count(*) from public.lessons where course_id=target_course)<=20 and exists(
    select 1 from public.lessons l where l.course_id=target_course and not exists(select 1 from jsonb_array_elements(bank) as entries(item) where item->>'lessonId'=l.id)
  ) then raise exception 'The question bank must cover every lesson when the course has at most 20 lessons.'; end if;
end;
$$;
revoke all on function public.pap_validate_assessment_bank(text,jsonb) from public,anon,authenticated;
grant execute on function public.pap_validate_assessment_bank(text,jsonb) to service_role;

create or replace function public.stage_course_assessment(target_course text, bank jsonb, expected_signature text) returns void
language plpgsql security definer set search_path = '' as $$
declare source jsonb;
begin
  perform pg_advisory_xact_lock(hashtextextended('assessment:'||target_course,0));
  source := public.pap_assessment_source(target_course);
  if source is null or expected_signature is distinct from md5(source::text) then raise exception 'Course content changed. Scan and generate a fresh draft.'; end if;
  perform public.pap_validate_assessment_bank(target_course,bank);
  insert into public.course_assessment_drafts(course_id,questions,source_signature,source_snapshot,status)
  values(target_course,bank,expected_signature,source,'needs_review') on conflict(course_id) do update
    set questions=excluded.questions,source_signature=excluded.source_signature,source_snapshot=excluded.source_snapshot,status='needs_review',created_at=now();
end;
$$;
revoke all on function public.stage_course_assessment(text,jsonb,text) from public,anon,authenticated;
grant execute on function public.stage_course_assessment(text,jsonb,text) to service_role;

create or replace function public.publish_course_assessment(target_course text, expected_signature text, expected_draft_hash text, reviewer text, reviewed_bank jsonb) returns uuid
language plpgsql security definer set search_path = '' as $$
declare draft public.course_assessment_drafts%rowtype; current_signature text; new_revision uuid:=gen_random_uuid();
begin
  if length(btrim(coalesce(reviewer,'')))<2 then raise exception 'Record who reviewed the questions before publishing.'; end if;
  perform pg_advisory_xact_lock(hashtextextended('assessment:'||target_course,0));
  select * into draft from public.course_assessment_drafts where course_id=target_course for update;
  current_signature:=md5(public.pap_assessment_source(target_course)::text);
  if not found or current_signature is null or draft.source_signature is distinct from current_signature
    or expected_signature is distinct from current_signature or expected_draft_hash is distinct from draft.draft_hash or reviewed_bank is distinct from draft.questions then
    raise exception 'The course or draft changed after review. Scan and review the latest draft.';
  end if;
  if draft.status='published' then raise exception 'This draft has already been published.'; end if;
  perform public.pap_validate_assessment_bank(target_course,draft.questions);
  insert into public.course_assessments(course_id,questions,revision,published_signature,needs_review,reviewed_by,published_at)
    values(target_course,draft.questions,new_revision,current_signature,false,btrim(reviewer),now())
  on conflict(course_id) do update set questions=excluded.questions,revision=excluded.revision,published_signature=excluded.published_signature,
    needs_review=false,reviewed_by=excluded.reviewed_by,published_at=excluded.published_at;
  update public.course_assessment_drafts set status='published' where course_id=target_course;
  return new_revision;
end;
$$;
revoke all on function public.publish_course_assessment(text,text,text,text,jsonb) from public,anon,authenticated;
grant execute on function public.publish_course_assessment(text,text,text,text,jsonb) to service_role;

create or replace function public.get_assessment_review_sources() returns setof jsonb
language sql stable security definer set search_path = '' as $$
  select jsonb_build_object('courseId',c.id,'title',c.title,'source',public.pap_assessment_source(c.id),
    'sourceSignature',md5(public.pap_assessment_source(c.id)::text),
    'needsReview',a.course_id is null or a.needs_review or a.published_signature is distinct from md5(public.pap_assessment_source(c.id)::text),
    'draft',case when d.course_id is null then null else jsonb_build_object('questions',d.questions,'sourceSignature',d.source_signature,'draftHash',d.draft_hash,'status',d.status) end)
  from public.courses c left join public.course_assessments a on a.course_id=c.id
    left join public.course_assessment_drafts d on d.course_id=c.id where c.is_published order by c.id;
$$;
revoke all on function public.get_assessment_review_sources() from public,anon,authenticated;
grant execute on function public.get_assessment_review_sources() to service_role;

create or replace function public.pap_mark_assessment_for_review() returns trigger
language plpgsql security definer set search_path = '' as $$
declare old_course text; new_course text;
begin
  if tg_op='UPDATE' then
    if tg_table_name='courses' and (to_jsonb(old)-array['image_url','image_alt','updated_at','duration_minutes','instructor_name','is_demo'])=(to_jsonb(new)-array['image_url','image_alt','updated_at','duration_minutes','instructor_name','is_demo']) then return null; end if;
    if tg_table_name='lessons' and (to_jsonb(old)-array['video_url','duration_minutes'])=(to_jsonb(new)-array['video_url','duration_minutes']) then return null; end if;
    if tg_table_name='course_modules' and to_jsonb(old)=to_jsonb(new) then return null; end if;
  end if;
  if tg_op<>'INSERT' then old_course:=case when tg_table_name='courses' then to_jsonb(old)->>'id' else to_jsonb(old)->>'course_id' end; end if;
  if tg_op<>'DELETE' then new_course:=case when tg_table_name='courses' then to_jsonb(new)->>'id' else to_jsonb(new)->>'course_id' end; end if;
  update public.course_assessments set needs_review=true where course_id in (old_course,new_course);
  update public.course_assessment_drafts set status='stale' where course_id in (old_course,new_course);
  return null;
end;
$$;
revoke all on function public.pap_mark_assessment_for_review() from public,anon,authenticated;
drop trigger if exists assessment_course_changed on public.courses;
create trigger assessment_course_changed after update on public.courses for each row execute function public.pap_mark_assessment_for_review();
drop trigger if exists assessment_module_changed on public.course_modules;
create trigger assessment_module_changed after insert or update or delete on public.course_modules for each row execute function public.pap_mark_assessment_for_review();
drop trigger if exists assessment_lesson_changed on public.lessons;
create trigger assessment_lesson_changed after insert or update or delete on public.lessons for each row execute function public.pap_mark_assessment_for_review();

-- A submission must match the reviewed version shown to the student.
drop function if exists public.submit_course_assessment(text,jsonb);
create or replace function public.submit_course_assessment(target_course text, submitted_answers jsonb, expected_revision uuid) returns jsonb
language plpgsql security definer set search_path = '' as $$
declare
  student uuid := auth.uid(); bank jsonb; question jsonb; selected integer; published public.course_assessments%rowtype;
  correct integer := 0; total integer; score_value integer; review jsonb := '[]'; outcome jsonb;
  attempt_id uuid := gen_random_uuid(); submitted_at timestamptz := now();
begin
  if student is null or not exists (
    select 1 from public.enrollments e join public.courses c on c.id = e.course_id
    where e.user_id = student and e.course_id = target_course and c.is_published
  ) then raise exception 'Sign in and enroll in this course before submitting.'; end if;
  perform 1 from public.enrollments where user_id = student and course_id = target_course for update;
  if not exists (select 1 from public.lessons where course_id = target_course) or exists (
    select 1 from public.lessons l where l.course_id = target_course and not exists (
      select 1 from public.lesson_progress p where p.user_id = student and p.course_id = target_course and p.lesson_id = l.id
    )
  ) then raise exception 'Complete all course lessons before taking the assessment.'; end if;
  select * into published from public.course_assessments where course_id=target_course for share;
  if not found or published.needs_review or published.published_signature is distinct from md5(public.pap_assessment_source(target_course)::text) then
    raise exception 'This assessment is being reviewed after a course update. Please return later.';
  end if;
  if expected_revision is distinct from published.revision then raise exception 'The assessment changed. Reload to answer the current questions.'; end if;
  bank:=published.questions;
  total := jsonb_array_length(bank);
  if submitted_answers is null or jsonb_typeof(submitted_answers) <> 'object' then
    raise exception 'Answer every question before submitting.';
  end if;
  if (select count(*) from jsonb_object_keys(submitted_answers)) <> total then
    raise exception 'Answer every question before submitting.';
  end if;
  for question in select value from jsonb_array_elements(bank) loop
    if not (submitted_answers ? (question->>'id')) or
      jsonb_typeof(submitted_answers->(question->>'id')) <> 'number' or
      (submitted_answers->>(question->>'id')) !~ '^[0-3]$' then
      raise exception 'Choose a valid answer for every question.';
    end if;
    selected := (submitted_answers->>(question->>'id'))::integer;
    if selected = (question->>'correctIndex')::integer then correct := correct + 1; end if;
    review := review || jsonb_build_array(jsonb_build_object(
      'id', question->>'id', 'prompt', question->>'prompt', 'options', question->'options',
      'selectedIndex', selected, 'correctIndex', (question->>'correctIndex')::integer,
      'explanation', question->>'explanation'
    ));
  end loop;
  score_value := round(correct * 100.0 / total);
  outcome := jsonb_build_object('id', attempt_id, 'score', score_value, 'correct', correct,
    'total', total, 'passed', score_value >= 60, 'passMark', 60, 'revision',published.revision, 'review', review, 'submittedAt', submitted_at);
  insert into public.assessment_attempts(id, user_id, course_id, score, result, created_at, assessment_revision)
    values(attempt_id, student, target_course, score_value, outcome, submitted_at, published.revision);
  return outcome;
end;
$$;
revoke all on function public.submit_course_assessment(text, jsonb, uuid) from public, anon, authenticated;
grant execute on function public.submit_course_assessment(text, jsonb, uuid) to authenticated;

create or replace function public.get_course_assessment(target_course text) returns jsonb
language plpgsql security definer set search_path = '' as $$
declare student uuid:=auth.uid(); published public.course_assessments%rowtype; latest jsonb; previous jsonb; best integer; pending boolean;
begin
  if student is null or not exists(select 1 from public.enrollments e join public.courses c on c.id=e.course_id where e.user_id=student and e.course_id=target_course and c.is_published)
    then raise exception 'Sign in and enroll in this course to access its assessment.'; end if;
  select * into published from public.course_assessments where course_id=target_course;
  pending:=not found or published.needs_review or published.published_signature is distinct from md5(public.pap_assessment_source(target_course)::text);
  select result into latest from public.assessment_attempts where user_id=student and course_id=target_course and assessment_revision=published.revision order by created_at desc,id desc limit 1;
  select result into previous from public.assessment_attempts where user_id=student and course_id=target_course and assessment_revision is distinct from published.revision order by created_at desc,id desc limit 1;
  select max(score) into best from public.assessment_attempts where user_id=student and course_id=target_course and assessment_revision=published.revision;
  return jsonb_build_object('revision',published.revision,'needsReview',pending,'passMark',60,'latestResult',latest,'previousResult',previous,'bestScore',best,
    'questions',case when pending then '[]'::jsonb else (select jsonb_agg(jsonb_build_object('id',q->>'id','lessonId',q->>'lessonId','prompt',q->>'prompt','options',q->'options') order by position)
      from jsonb_array_elements(published.questions) with ordinality as items(q,position)) end);
end;
$$;
revoke all on function public.get_course_assessment(text) from public,anon,authenticated;
grant execute on function public.get_course_assessment(text) to authenticated;

-- Initial 20-question drafts. Review against the captured live course before publication.
do $seed$ begin
  if exists(select 1 from public.courses where id='academic-excellence') and not exists(select 1 from public.course_assessment_drafts where course_id='academic-excellence') then
    begin
      perform public.stage_course_assessment('academic-excellence', $questions$[{"id": "q1", "prompt": "Which study goal is the most specific?", "options": ["Complete five practice problems by Friday", "Become better at everything", "Study whenever possible", "Never make a mistake"], "correctIndex": 0, "explanation": "A specific goal describes an observable task and a deadline.", "lessonId": "setting-goals-you-can-act-on"}, {"id": "q2", "prompt": "Two assignments are due tomorrow and next month. What should guide your planning?", "options": ["Ignoring both until the deadline passes", "Urgency, importance, and the time each task needs", "Only how colourful the assignment looks", "Always choosing the longest deadline first"], "correctIndex": 1, "explanation": "Planning considers deadlines, importance, and the effort needed for each task.", "lessonId": "planning-your-study-week"}, {"id": "q3", "prompt": "Which notes are easiest to use for revision?", "options": ["Unlabelled fragments from different topics", "An unbroken copy of every word", "Organised key ideas, questions, and examples", "Only the lecture date"], "correctIndex": 2, "explanation": "Organised ideas, questions, and examples help you revisit and test your understanding.", "lessonId": "active-reading-and-useful-notes"}, {"id": "q4", "prompt": "What should you do after getting a practice question wrong?", "options": ["Memorise only the question number", "Hide the result", "Stop studying the subject", "Identify the error, review the idea, and try again"], "correctIndex": 3, "explanation": "Reviewing the reason for an error helps you decide what to practise next.", "lessonId": "using-feedback-to-improve"}, {"id": "q5", "prompt": "Your study plan keeps slipping. What is a useful next step?", "options": ["Review what got in the way and adjust the plan", "Keep the same unrealistic schedule", "Remove every break", "Wait for motivation without changing anything"], "correctIndex": 0, "explanation": "A study plan should adapt to your commitments and what you learn about your working habits.", "lessonId": "putting-your-study-plan-into-practice"}, {"id": "q6", "lessonId": "defining-academic-success", "prompt": "Which definition of academic success gives a student a useful direction?", "options": ["Never needing help", "Identifying meaningful learning goals and working towards them", "Only comparing themselves with others", "Avoiding every difficult task"], "correctIndex": 1, "explanation": "Meaningful goals give a student a direction for planning and reviewing progress."}, {"id": "q7", "lessonId": "setting-goals-you-can-act-on", "prompt": "A student wants to improve essay writing. Which next step is actionable?", "options": ["Wait until the next exam", "Think about writing someday", "Draft one introduction and request feedback this week", "Become perfect immediately"], "correctIndex": 2, "explanation": "An observable task and a time frame turn a general aim into an action."}, {"id": "q8", "lessonId": "planning-your-study-week", "prompt": "What should you place in your weekly plan before adding study tasks?", "options": ["Only leisure ideas", "Other students' schedules without checking yours", "Tasks you have already finished", "Fixed commitments such as classes and deadlines"], "correctIndex": 3, "explanation": "Fixed commitments show the time actually available for additional work."}, {"id": "q9", "lessonId": "active-reading-and-useful-notes", "prompt": "Which activity makes reading more active?", "options": ["Asking questions and summarising the main idea", "Counting the paragraphs only", "Moving your eyes across the page without checking meaning", "Copying every sentence automatically"], "correctIndex": 0, "explanation": "Questions and summaries require you to think about the meaning of what you read."}, {"id": "q10", "lessonId": "revision-that-supports-recall", "prompt": "Which revision task directly checks recall?", "options": ["Looking at the answer while repeating it", "Closing the notes and answering a practice question", "Rewriting the title neatly", "Reading without any pauses"], "correctIndex": 1, "explanation": "Trying an answer without the notes checks what you can retrieve."}, {"id": "q11", "lessonId": "preparing-for-assessments", "prompt": "What makes assessment preparation focused?", "options": ["Only buying stationery", "Choosing topics at random every time", "Reviewing the required topics and practising relevant tasks", "Ignoring the topics that will be assessed"], "correctIndex": 2, "explanation": "Preparation should connect the assessed topics with practice of the required tasks."}, {"id": "q12", "lessonId": "using-feedback-to-improve", "prompt": "A teacher says an argument needs evidence. What is an appropriate response?", "options": ["Change only the font", "Remove every claim", "Ignore the feedback", "Add relevant evidence and explain how it supports the point"], "correctIndex": 3, "explanation": "Acting on feedback means addressing the specific issue it identifies."}, {"id": "q13", "lessonId": "putting-your-study-plan-into-practice", "prompt": "A large task feels difficult to start. Which approach makes the next step clearer?", "options": ["Break it into small tasks and choose the first one", "Remove the task from view", "Wait until the deadline has passed", "Plan to do everything in one undefined session"], "correctIndex": 0, "explanation": "Smaller tasks turn a large objective into a sequence of manageable actions."}, {"id": "q14", "lessonId": "planning-your-study-week", "prompt": "Why leave some flexible time in a weekly plan?", "options": ["To make deadlines optional", "To accommodate tasks that take longer or commitments that change", "To avoid all planned work", "To guarantee no unexpected events occur"], "correctIndex": 1, "explanation": "Flexible time helps a plan respond to normal changes and uncertain task lengths."}, {"id": "q15", "lessonId": "active-reading-and-useful-notes", "prompt": "After reading a section, which note is most useful for checking understanding?", "options": ["Only the page colour", "A copy with no thought about meaning", "A short summary and a question about the key idea", "Only the number of words"], "correctIndex": 2, "explanation": "A summary and a question help you process and revisit the main idea."}, {"id": "q16", "lessonId": "revision-that-supports-recall", "prompt": "You recognise an answer when reading but cannot produce it alone. What needs more practice?", "options": ["Recognising the book cover", "Choosing a different pen", "Counting how often the title appears", "Recalling the idea without looking at the answer"], "correctIndex": 3, "explanation": "Recognising an answer and independently recalling it are different tasks."}, {"id": "q17", "lessonId": "preparing-for-assessments", "prompt": "Why review the instructions before starting a practice assessment?", "options": ["To understand the tasks and response requirements", "To replace subject knowledge", "To avoid answering the questions", "To memorise only the header"], "correctIndex": 0, "explanation": "Instructions explain what kind of response is required and how to approach the task."}, {"id": "q18", "lessonId": "using-feedback-to-improve", "prompt": "What helps turn repeated feedback into improvement?", "options": ["Keeping it unread", "Identifying a recurring issue and practising a targeted change", "Assuming it applies to everyone else", "Discarding earlier work"], "correctIndex": 1, "explanation": "A recurring issue can guide a specific practice goal."}, {"id": "q19", "lessonId": "setting-goals-you-can-act-on", "prompt": "A goal is too large for the available week. What is a realistic adjustment?", "options": ["Avoid all planning", "Assume the deadline will disappear", "Reduce the scope into achievable milestones", "Keep the target and remove sleep"], "correctIndex": 2, "explanation": "Achievable milestones help connect a larger goal with the time available."}, {"id": "q20", "lessonId": "putting-your-study-plan-into-practice", "prompt": "At the end of a study week, what should a plan review compare?", "options": ["Only notebook prices", "Only other people's marks", "Only the number of hours written on the plan", "Planned tasks, completed work, and what needs adjusting"], "correctIndex": 3, "explanation": "Comparing the plan with completed work helps identify practical adjustments."}]$questions$::jsonb, md5(public.pap_assessment_source('academic-excellence')::text));
    exception when others then
      raise notice 'Draft for academic-excellence needs regeneration for this curriculum: %',sqlerrm;
    end;
  end if;
end $seed$;

do $seed$ begin
  if exists(select 1 from public.courses where id='effective-communication') and not exists(select 1 from public.course_assessment_drafts where course_id='effective-communication') then
    begin
      perform public.stage_course_assessment('effective-communication', $questions$[{"id": "q1", "prompt": "What helps make a message clear?", "options": ["Including every unrelated detail", "Stating the main point and supporting it with relevant details", "Using unfamiliar words whenever possible", "Avoiding the purpose of the conversation"], "correctIndex": 1, "explanation": "A clear main point and relevant supporting details help the listener follow your message.", "lessonId": "organising-your-ideas"}, {"id": "q2", "prompt": "Which action demonstrates active listening?", "options": ["Checking your phone throughout", "Interrupting to finish every sentence", "Listening, then summarising to check your understanding", "Planning your reply while someone speaks"], "correctIndex": 2, "explanation": "Summarising and checking what you heard helps establish shared understanding.", "lessonId": "active-listening"}, {"id": "q3", "prompt": "You are unsure what a teammate means. What should you do?", "options": ["Pretend you understood", "Assume the worst interpretation", "Change the topic immediately", "Ask a respectful clarifying question"], "correctIndex": 3, "explanation": "A clarifying question helps resolve uncertainty without making assumptions.", "lessonId": "asking-better-questions"}, {"id": "q4", "prompt": "Which feedback is most constructive?", "options": ["Your main point was clear; adding an example could make it stronger", "This is useless", "You are bad at everything", "Everyone dislikes your work"], "correctIndex": 0, "explanation": "Constructive feedback is specific, respectful, and suggests an actionable improvement.", "lessonId": "giving-and-receiving-feedback"}, {"id": "q5", "prompt": "Why adapt a message to your audience?", "options": ["To avoid communicating any information", "To make the language and detail appropriate for the listener", "To give everyone identical technical detail", "To make the message longer in every case"], "correctIndex": 1, "explanation": "Considering the audience helps you choose understandable language and a useful level of detail.", "lessonId": "choosing-words-with-care"}, {"id": "q6", "lessonId": "the-purpose-of-communication", "prompt": "Before preparing a message, what should you clarify first?", "options": ["How to include every unrelated fact", "How to make the message longest", "What you want the audience to understand or do", "Which font is most decorative"], "correctIndex": 2, "explanation": "A clear purpose helps determine which information belongs in a message."}, {"id": "q7", "lessonId": "organising-your-ideas", "prompt": "Which sequence gives a short presentation a clear structure?", "options": ["Every detail in random order", "Unrelated details, no conclusion, then a title", "A conclusion without any explanation", "Main point, relevant support, and a brief conclusion"], "correctIndex": 3, "explanation": "A main point followed by relevant support and a conclusion gives the audience a clear path."}, {"id": "q8", "lessonId": "choosing-words-with-care", "prompt": "A listener is unfamiliar with your subject. What helps?", "options": ["Choose familiar words and explain necessary terms", "Speak faster whenever they look confused", "Avoid examples", "Use unexplained abbreviations throughout"], "correctIndex": 0, "explanation": "Familiar language and explanations of essential terms help make a message understandable."}, {"id": "q9", "lessonId": "active-listening", "prompt": "Which question checks whether you understood a speaker?", "options": ["Will you stop talking now?", "Do you mean the deadline moved to Friday?", "Why are you always wrong?", "Can we ignore what you said?"], "correctIndex": 1, "explanation": "Checking a specific interpretation gives the speaker a chance to confirm or correct it."}, {"id": "q10", "lessonId": "asking-better-questions", "prompt": "Which is an open question?", "options": ["Is the answer yes?", "Did you attend?", "What made that part of the project difficult?", "Was it Tuesday?"], "correctIndex": 2, "explanation": "An open question invites an explanation rather than only a yes, no, or short factual reply."}, {"id": "q11", "lessonId": "understanding-nonverbal-cues", "prompt": "Someone's facial expression seems different from their words. What is a careful response?", "options": ["Ignore everything they say", "Assume the expression has one fixed meaning", "Tell others the person is lying", "Consider the context and ask respectfully if clarification is needed"], "correctIndex": 3, "explanation": "Nonverbal cues need context; asking can be more reliable than assuming one meaning."}, {"id": "q12", "lessonId": "giving-and-receiving-feedback", "prompt": "What is a useful response to feedback you do not fully understand?", "options": ["Ask for a specific example and the suggested improvement", "Pretend to agree without understanding", "Make the discussion personal", "Reject it before hearing the details"], "correctIndex": 0, "explanation": "Examples and clarification turn broad feedback into something you can act on."}, {"id": "q13", "lessonId": "speaking-in-a-group", "prompt": "What can help a speaker prepare for a group presentation?", "options": ["Read unrelated material only", "Identify the key points and rehearse within the available time", "Add more points than time allows", "Avoid practising the opening"], "correctIndex": 1, "explanation": "Selecting key points and rehearsing helps align the message with its time limit."}, {"id": "q14", "lessonId": "communicating-through-disagreement", "prompt": "Which response keeps a discussion focused on the issue?", "options": ["Everyone should ignore you", "There is no point listening", "I see the deadline differently; can we compare the instructions?", "You never understand anything"], "correctIndex": 2, "explanation": "Referring to the specific issue and shared information supports a constructive discussion."}, {"id": "q15", "lessonId": "organising-your-ideas", "prompt": "Why remove a detail that does not support the main point?", "options": ["Listeners should never ask questions", "Every short message must omit evidence", "Long messages are always incorrect", "Unrelated details can distract from the message's purpose"], "correctIndex": 3, "explanation": "Selecting relevant details helps the audience focus on the intended point."}, {"id": "q16", "lessonId": "choosing-words-with-care", "prompt": "Which instruction is the clearest?", "options": ["Send the two-page draft by 3 p.m. on Thursday", "Arrange everything at some point", "Make it like before", "Do the thing soon"], "correctIndex": 0, "explanation": "A clear instruction specifies the task, expected output, and deadline."}, {"id": "q17", "lessonId": "active-listening", "prompt": "Why let someone finish before replying?", "options": ["To make the conversation longer only", "To hear the complete point before forming a response", "To avoid ever asking questions", "To agree automatically"], "correctIndex": 1, "explanation": "Hearing the full point reduces the risk of responding to an incomplete interpretation."}, {"id": "q18", "lessonId": "asking-better-questions", "prompt": "A teammate says a task is 'nearly done'. Which question gives useful clarification?", "options": ["Can we stop planning forever?", "Do you dislike the project?", "Which parts remain, and when do you expect to finish them?", "Why does nothing ever work?"], "correctIndex": 2, "explanation": "Asking about remaining work and expected completion clarifies a vague progress update."}, {"id": "q19", "lessonId": "speaking-in-a-group", "prompt": "Which practice supports participation in a group discussion?", "options": ["Changing topics whenever others speak", "Speaking over every contribution", "Keeping the purpose unclear", "Making a concise point and allowing others to respond"], "correctIndex": 3, "explanation": "Concise contributions and room for responses support shared participation."}, {"id": "q20", "lessonId": "communicating-through-disagreement", "prompt": "After agreeing on a next step, what helps avoid another misunderstanding?", "options": ["Summarise the action, person responsible, and timing", "Avoid recording the agreement", "Introduce a new unrelated issue", "Assume everyone remembers identical details"], "correctIndex": 0, "explanation": "A specific summary helps establish a shared understanding of the agreement."}]$questions$::jsonb, md5(public.pap_assessment_source('effective-communication')::text));
    exception when others then
      raise notice 'Draft for effective-communication needs regeneration for this curriculum: %',sqlerrm;
    end;
  end if;
end $seed$;

do $seed$ begin
  if exists(select 1 from public.courses where id='emotional-intelligence') and not exists(select 1 from public.course_assessment_drafts where course_id='emotional-intelligence') then
    begin
      perform public.stage_course_assessment('emotional-intelligence', $questions$[{"id": "q1", "prompt": "Which action shows self-awareness?", "options": ["Pretending emotions never occur", "Responding before thinking", "Noticing and naming your emotion before responding", "Assuming other people caused every feeling"], "correctIndex": 2, "explanation": "Self-awareness includes recognising your feelings and noticing how they affect your response.", "lessonId": "developing-self-awareness"}, {"id": "q2", "prompt": "What is an emotional trigger?", "options": ["A way to remove all feelings", "A guarantee that everyone reacts the same way", "An instruction to argue", "A situation or experience that prompts an emotional response"], "correctIndex": 3, "explanation": "A trigger is something that prompts an emotional response; different people may respond differently.", "lessonId": "recognising-emotional-triggers"}, {"id": "q3", "prompt": "Which response best demonstrates empathy?", "options": ["Trying to understand another person's perspective", "Making every conversation about yourself", "Assuming you know how everyone feels", "Immediately judging someone"], "correctIndex": 0, "explanation": "Empathy involves trying to understand someone else's experience and perspective.", "lessonId": "practising-empathy"}, {"id": "q4", "prompt": "During a disagreement, which response leaves room for a thoughtful discussion?", "options": ["Using insults", "Pausing, listening, and explaining your view calmly", "Interrupting repeatedly", "Sending an angry message immediately"], "correctIndex": 1, "explanation": "Pausing and listening can help you choose a response rather than reacting impulsively.", "lessonId": "navigating-disagreements"}, {"id": "q5", "prompt": "How can reflection support personal growth?", "options": ["By proving that you are always right", "By replacing every conversation", "By noticing patterns and considering a different response next time", "By ensuring you never experience emotions"], "correctIndex": 2, "explanation": "Reflection helps you notice patterns and choose actions you may want to change.", "lessonId": "your-reflection-plan"}, {"id": "q6", "lessonId": "understanding-your-emotions", "prompt": "Which statement names an emotion rather than judging another person?", "options": ["Nothing can ever improve", "You always ruin everything", "Everyone is against me", "I feel disappointed about what happened"], "correctIndex": 3, "explanation": "Naming your own feeling is different from making a broad judgment about someone else."}, {"id": "q7", "lessonId": "recognising-emotional-triggers", "prompt": "Why note the situation that came before an emotional reaction?", "options": ["To identify patterns in what prompts the reaction", "To avoid understanding the feeling", "To blame someone automatically", "To prove that all reactions are identical"], "correctIndex": 0, "explanation": "Noticing what happened before a reaction can help identify recurring triggers."}, {"id": "q8", "lessonId": "developing-self-awareness", "prompt": "Which reflection shows awareness of both feeling and behaviour?", "options": ["My actions cannot change", "I felt frustrated and noticed that I interrupted", "I never have any reactions", "Other people decide everything I do"], "correctIndex": 1, "explanation": "Connecting a feeling with an observable action helps you reflect on your response."}, {"id": "q9", "lessonId": "pausing-before-reacting", "prompt": "What is the purpose of pausing before responding to a difficult message?", "options": ["To avoid every future conversation", "To prove emotions are unimportant", "To give yourself time to choose a considered response", "To guarantee the other person agrees"], "correctIndex": 2, "explanation": "A pause creates space to consider how you want to respond."}, {"id": "q10", "lessonId": "managing-everyday-stress", "prompt": "Several deadlines are making a student's week feel unmanageable. Which action addresses the workload?", "options": ["Wait until every task is overdue", "Pretend the deadlines do not exist", "Agree to every extra task", "List the tasks and make a realistic priority plan"], "correctIndex": 3, "explanation": "Listing and prioritising tasks helps clarify the workload and the next action."}, {"id": "q11", "lessonId": "building-helpful-habits", "prompt": "Which plan describes a repeatable reflection habit?", "options": ["Spend five minutes after class noting one feeling and response", "Wait until you remember many months later", "Only reflect on other people's actions", "Reflect once without a plan"], "correctIndex": 0, "explanation": "A specific routine linked to a regular situation makes the habit repeatable."}, {"id": "q12", "lessonId": "practising-empathy", "prompt": "A classmate seems quiet after receiving feedback. Which response shows interest without assuming their feelings?", "options": ["Dismiss the feedback immediately", "Ask how they are feeling and listen", "Tell everyone what you think they feel", "Insist you already know the reason"], "correctIndex": 1, "explanation": "Asking and listening gives the person space to describe their own experience."}, {"id": "q13", "lessonId": "seeing-another-perspective", "prompt": "Two classmates interpret the same event differently. What can help them understand each other?", "options": ["Refuse to hear any explanation", "Repeat the same accusation", "Ask what each person noticed and how they interpreted it", "Assume one person must be dishonest"], "correctIndex": 2, "explanation": "Different experiences and interpretations can be explored through respectful questions."}, {"id": "q14", "lessonId": "navigating-disagreements", "prompt": "Which sentence focuses a disagreement on a specific issue?", "options": ["You never do anything useful", "You are always impossible", "Everyone knows you are wrong", "We agreed on Tuesday, but the draft arrived Thursday; can we discuss the delay?"], "correctIndex": 3, "explanation": "Specific observations make the issue clearer than broad personal accusations."}, {"id": "q15", "lessonId": "your-reflection-plan", "prompt": "Which entry would make a reflection plan useful for next time?", "options": ["What happened, how you responded, and one alternative to try", "Only what others should change", "A claim that nothing can improve", "Only the name of the day"], "correctIndex": 0, "explanation": "A useful reflection connects an event and response with a possible next action."}, {"id": "q16", "lessonId": "understanding-your-emotions", "prompt": "What is the distinction between a feeling and an action?", "options": ["Feelings only exist after an action", "You can notice a feeling and still choose how to act", "They are always the same", "Actions can never be chosen"], "correctIndex": 1, "explanation": "Recognising an emotion does not determine a single unavoidable behaviour."}, {"id": "q17", "lessonId": "recognising-emotional-triggers", "prompt": "What makes a trigger journal more informative?", "options": ["Assuming every event had the same cause", "Recording only other people's mistakes", "Recording the situation, feeling, and response across several events", "Writing only unrelated dates"], "correctIndex": 2, "explanation": "Several specific observations make patterns easier to notice."}, {"id": "q18", "lessonId": "practising-empathy", "prompt": "Does understanding another person's perspective require agreeing with every claim?", "options": ["No, because listening has no purpose", "Yes, understanding and agreement are identical", "Yes, disagreement makes listening impossible", "No, you can understand a perspective while holding a different view"], "correctIndex": 3, "explanation": "Understanding and agreement are different; respectful listening can occur alongside disagreement."}, {"id": "q19", "lessonId": "navigating-disagreements", "prompt": "You realise you interrupted a teammate. Which response takes responsibility?", "options": ["Acknowledge it and invite them to finish", "Blame the whole team", "Interrupt again to explain why", "Deny that the interruption happened"], "correctIndex": 0, "explanation": "Acknowledging a specific action and making space for the other person supports constructive discussion."}, {"id": "q20", "lessonId": "your-reflection-plan", "prompt": "How can you check whether a new response is helping?", "options": ["Only ask whether you won the argument", "Review later situations and consider the effects of your response", "Assume it always works", "Avoid looking at what happened"], "correctIndex": 1, "explanation": "Reviewing later experiences helps you decide what to keep or adjust."}]$questions$::jsonb, md5(public.pap_assessment_source('emotional-intelligence')::text));
    exception when others then
      raise notice 'Draft for emotional-intelligence needs regeneration for this curriculum: %',sqlerrm;
    end;
  end if;
end $seed$;

do $seed$ begin
  if exists(select 1 from public.courses where id='financial-intelligence') and not exists(select 1 from public.course_assessment_drafts where course_id='financial-intelligence') then
    begin
      perform public.stage_course_assessment('financial-intelligence', $questions$[{"id": "q1", "prompt": "A student receives ₦30,000 and spends ₦22,000. How much remains?", "options": ["₦22,000", "₦30,000", "₦52,000", "₦8,000"], "correctIndex": 3, "explanation": "Subtract expenses from income: ₦30,000 − ₦22,000 = ₦8,000.", "lessonId": "understanding-income-and-expenses"}, {"id": "q2", "prompt": "Which item is most clearly a need for attending a class?", "options": ["Transport to the classroom", "An extra entertainment package", "A new gaming subscription", "A designer bag"], "correctIndex": 0, "explanation": "A need supports an essential activity, such as travelling to an in-person class.", "lessonId": "needs-wants-and-priorities"}, {"id": "q3", "prompt": "What does a budget record?", "options": ["Only large purchases", "Planned income and expenses", "Only the things you want", "Only money borrowed"], "correctIndex": 1, "explanation": "A budget brings planned income and expenses together so you can compare them.", "lessonId": "building-a-student-budget"}, {"id": "q4", "prompt": "You plan to save ₦12,000 over four months in equal amounts. What is the monthly amount?", "options": ["₦8,000", "₦48,000", "₦3,000", "₦4,000"], "correctIndex": 2, "explanation": "Divide the total goal by the number of months: ₦12,000 ÷ 4 = ₦3,000.", "lessonId": "saving-with-intention"}, {"id": "q5", "prompt": "Why keep a record of small daily expenses?", "options": ["Recording them increases income", "Only cash payments count", "They never affect a budget", "They add up and help explain spending patterns"], "correctIndex": 3, "explanation": "Small purchases can add up. Recording them makes spending patterns easier to see.", "lessonId": "tracking-your-spending"}, {"id": "q6", "lessonId": "money-habits-and-values", "prompt": "You notice you often buy things to match friends. What would help you understand this habit?", "options": ["Review what prompts the purchases and whether they fit your priorities", "Ignore every receipt", "Assume friends have the same budget", "Increase spending without checking income"], "correctIndex": 0, "explanation": "Reflecting on what drives a purchase helps connect money habits with personal priorities."}, {"id": "q7", "lessonId": "setting-financial-goals", "prompt": "Which financial goal is measurable?", "options": ["Spend without planning", "Save ₦2,000 each month for five months", "Never think about money", "Have more money someday"], "correctIndex": 1, "explanation": "An amount and a time period make progress measurable."}, {"id": "q8", "lessonId": "understanding-income-and-expenses", "prompt": "Which entry belongs under income in a student budget?", "options": ["A phone bill paid", "Transport fare paid", "An allowance received", "A textbook bought"], "correctIndex": 2, "explanation": "Income is money received; the other entries describe money spent."}, {"id": "q9", "lessonId": "tracking-your-spending", "prompt": "A student pays ₦500 daily for snacks over six days. What is the total?", "options": ["₦500", "₦2,500", "₦6,000", "₦3,000"], "correctIndex": 3, "explanation": "Multiply the daily expense by the number of days: ₦500 × 6 = ₦3,000."}, {"id": "q10", "lessonId": "building-a-student-budget", "prompt": "Planned expenses exceed planned income. What does the budget show?", "options": ["A shortfall that needs addressing", "A guaranteed surplus", "That expenses are irrelevant", "That every purchase is affordable"], "correctIndex": 0, "explanation": "When expenses exceed income, the difference is a shortfall."}, {"id": "q11", "lessonId": "saving-with-intention", "prompt": "What makes a savings goal easier to track?", "options": ["Avoiding records", "Giving the goal a target amount and date", "Counting money already spent as savings", "Changing the target every day"], "correctIndex": 1, "explanation": "A target amount and date provide a clear basis for tracking progress."}, {"id": "q12", "lessonId": "preparing-for-unexpected-costs", "prompt": "What is the purpose of setting money aside for unexpected costs?", "options": ["To turn every want into a need", "To make all future costs predictable", "To cover unplanned expenses when they occur", "To remove the need for a budget"], "correctIndex": 2, "explanation": "A reserve can help cover expenses that were not included in the original plan."}, {"id": "q13", "lessonId": "creating-a-budget-that-works", "prompt": "Your recorded transport cost is higher than your original estimate. What should a useful budget review do?", "options": ["Delete the record", "Keep the estimate and ignore the difference", "Stop tracking transport", "Use the actual cost to update the plan"], "correctIndex": 3, "explanation": "Comparing actual expenses with estimates helps make the next budget more realistic."}, {"id": "q14", "lessonId": "understanding-borrowing", "prompt": "An item costs ₦10,000 in cash or five payments of ₦2,400. What is the total of the payments?", "options": ["₦12,000", "₦10,000", "₦2,400", "₦7,600"], "correctIndex": 0, "explanation": "Five payments of ₦2,400 total ₦12,000; payment size alone does not show the total cost."}, {"id": "q15", "lessonId": "recognising-financial-risks", "prompt": "A message promises a large reward but hides the conditions. What information is missing?", "options": ["The number of emojis used", "Clear terms explaining costs, conditions, and risks", "The sender's favourite subject", "The colour of the sender's logo"], "correctIndex": 1, "explanation": "Understanding a financial claim requires clear terms, including its costs, conditions, and risks."}, {"id": "q16", "lessonId": "your-personal-money-plan", "prompt": "What should a personal money plan connect?", "options": ["A wish list without amounts", "Only other people's spending", "Your income, expenses, priorities, and goals", "Only purchases from last year"], "correctIndex": 2, "explanation": "A money plan connects available resources with expenses and personal priorities."}, {"id": "q17", "lessonId": "needs-wants-and-priorities", "prompt": "Why might the same purchase be a need for one person and a want for another?", "options": ["Needs are always identical", "Prices never change", "Wants always cost more", "Circumstances and responsibilities can differ"], "correctIndex": 3, "explanation": "A purchase's role depends on a person's circumstances, rather than its label alone."}, {"id": "q18", "lessonId": "setting-financial-goals", "prompt": "A goal is ₦15,000 and the amount saved is ₦6,000. How much remains to reach the goal?", "options": ["₦9,000", "₦21,000", "₦6,000", "₦15,000"], "correctIndex": 0, "explanation": "Subtract what has been saved from the target: ₦15,000 − ₦6,000 = ₦9,000."}, {"id": "q19", "lessonId": "building-a-student-budget", "prompt": "Why separate planned spending from actual spending?", "options": ["To count every expense twice", "To compare estimates with what really happened", "To hide unexpected costs", "To make the budget harder to read"], "correctIndex": 1, "explanation": "Keeping both figures lets you compare the plan with actual spending."}, {"id": "q20", "lessonId": "your-personal-money-plan", "prompt": "A student's income changes. What makes their money plan responsive?", "options": ["Removing every record", "Ignoring the change", "Revisiting the budget and savings targets", "Assuming old estimates must stay fixed"], "correctIndex": 2, "explanation": "A plan should be reviewed when the resources or commitments it describes change."}]$questions$::jsonb, md5(public.pap_assessment_source('financial-intelligence')::text));
    exception when others then
      raise notice 'Draft for financial-intelligence needs regeneration for this curriculum: %',sqlerrm;
    end;
  end if;
end $seed$;

do $seed$ begin
  if exists(select 1 from public.courses where id='learning-styles') and not exists(select 1 from public.course_assessment_drafts where course_id='learning-styles') then
    begin
      perform public.stage_course_assessment('learning-styles', $questions$[{"id": "q1", "prompt": "What is a flexible approach to learning?", "options": ["Choosing methods that suit the task", "Only studying topics that feel easy", "Always using one method", "Avoiding unfamiliar tasks"], "correctIndex": 0, "explanation": "Different tasks benefit from different approaches. A flexible toolkit lets you adapt.", "lessonId": "choosing-a-strategy-for-the-task"}, {"id": "q2", "prompt": "Which activity is retrieval practice?", "options": ["Reading the same page without pausing", "Answering a question from memory before checking your notes", "Copying a paragraph while looking at it", "Highlighting every sentence"], "correctIndex": 1, "explanation": "Retrieval practice means trying to recall information before checking the answer.", "lessonId": "retrieval-practice-and-spaced-revision"}, {"id": "q3", "prompt": "What does spaced revision mean?", "options": ["Never reviewing previous work", "Only revising on exam day", "Returning to material across separate study sessions", "Doing all revision in one long sitting"], "correctIndex": 2, "explanation": "Spaced revision spreads review across separate sessions instead of concentrating it in one sitting.", "lessonId": "retrieval-practice-and-spaced-revision"}, {"id": "q4", "prompt": "After explaining a concept from memory, what should you do?", "options": ["Avoid looking at the topic again", "Replace the topic with something easier", "Assume every detail was correct", "Check your explanation and review any gaps"], "correctIndex": 3, "explanation": "Checking your explanation helps you identify and correct gaps in understanding.", "lessonId": "learning-through-explanation"}, {"id": "q5", "prompt": "Which is the clearest sign that you can use a new idea?", "options": ["You can apply it to a new example", "You read the title many times", "Your notes look colourful", "You recognise the page layout"], "correctIndex": 0, "explanation": "Applying an idea to a new example demonstrates understanding beyond recognising the material.", "lessonId": "practising-with-examples"}, {"id": "q6", "lessonId": "reflecting-on-your-study-habits", "prompt": "Which reflection gives useful information about a study habit?", "options": ["I will never change my approach", "After solving practice questions, I could explain the steps without notes", "I studied, so every method must work", "I like the colour of this book"], "correctIndex": 1, "explanation": "An observation about what you could do afterwards is more useful than a vague impression."}, {"id": "q7", "lessonId": "preferences-versus-effective-strategies", "prompt": "A study method feels comfortable, but you cannot answer questions afterwards. What does this suggest?", "options": ["Questions should be avoided", "There is no need to check understanding", "Comfort alone does not establish that learning has occurred", "The method must be effective for every task"], "correctIndex": 2, "explanation": "A preference describes comfort; checking performance helps assess whether a method supports understanding."}, {"id": "q8", "lessonId": "finding-your-study-rhythm", "prompt": "Which observation can help you choose a study time?", "options": ["The time another student always uses", "The most popular time on social media", "The longest possible session without a break", "When you can focus consistently around your commitments"], "correctIndex": 3, "explanation": "A routine should consider your attention and your real commitments."}, {"id": "q9", "lessonId": "making-useful-visual-notes", "prompt": "What makes a concept map useful?", "options": ["Showing meaningful links between key ideas", "Replacing every word with decoration", "Including unrelated images", "Using as many colours as possible"], "correctIndex": 0, "explanation": "A concept map helps when it makes relationships between ideas clear."}, {"id": "q10", "lessonId": "learning-through-explanation", "prompt": "You get stuck while explaining an idea to a classmate. What is a useful response?", "options": ["Avoid the topic", "Identify the unclear part and revisit it", "Pretend the explanation is complete", "Memorise the classmate's name"], "correctIndex": 1, "explanation": "Difficulty explaining a specific part can reveal a gap to review."}, {"id": "q11", "lessonId": "practising-with-examples", "prompt": "Why try a new example after studying a worked example?", "options": ["To avoid making any decisions", "To repeat the same wording without thinking", "To check whether you can apply the method independently", "To memorise the page number"], "correctIndex": 2, "explanation": "A new example checks whether you can use the method beyond the original demonstration."}, {"id": "q12", "lessonId": "retrieval-practice-and-spaced-revision", "prompt": "Which plan combines retrieval practice with spaced revision?", "options": ["Copy the same paragraph continuously", "Highlight notes once without testing yourself", "Read every page only on the final night", "Answer questions from memory on several separate days"], "correctIndex": 3, "explanation": "Recalling information across separate sessions combines both strategies."}, {"id": "q13", "lessonId": "choosing-a-strategy-for-the-task", "prompt": "You need to practise a calculation method. Which activity most directly matches the task?", "options": ["Working through calculation problems and checking the steps", "Memorising only the chapter title", "Reading a list of unrelated terms", "Choosing a new notebook cover"], "correctIndex": 0, "explanation": "Practising the calculation directly matches the skill the task requires."}, {"id": "q14", "lessonId": "designing-your-study-routine", "prompt": "What makes a study routine actionable?", "options": ["A schedule that ignores classes", "Specific tasks placed in realistic time slots", "A promise to study everything eventually", "A list without available time"], "correctIndex": 1, "explanation": "A routine becomes actionable when it connects a clear task to available time."}, {"id": "q15", "lessonId": "reflecting-and-adapting", "prompt": "A technique helps you remember terms but not explain relationships. What should you consider?", "options": ["Stop checking your understanding", "Assume the relationships do not matter", "Add an activity that practises explaining the relationships", "Use the technique for every possible task"], "correctIndex": 2, "explanation": "Different goals may require different activities; adapt the approach to the skill that needs work."}, {"id": "q16", "lessonId": "making-useful-visual-notes", "prompt": "Which visual note most directly shows the order of a process?", "options": ["A list of unrelated page numbers", "A random collection of pictures", "An unlabelled colour palette", "A labelled sequence with arrows between steps"], "correctIndex": 3, "explanation": "A sequence diagram can make the order and connections between steps visible."}, {"id": "q17", "lessonId": "learning-through-explanation", "prompt": "What is the purpose of explaining an idea in your own words?", "options": ["To check and express your understanding", "To change the idea's meaning on purpose", "To copy its exact spelling only", "To avoid checking it for accuracy"], "correctIndex": 0, "explanation": "Using your own words can reveal what you understand and what remains unclear."}, {"id": "q18", "lessonId": "practising-with-examples", "prompt": "After checking an incorrect practice answer, what should you record?", "options": ["Only the time of day", "The step that went wrong and how to correct it", "Only that the question was difficult", "Nothing about the method"], "correctIndex": 1, "explanation": "Recording the source of the error makes the next practice attempt more focused."}, {"id": "q19", "lessonId": "finding-your-study-rhythm", "prompt": "Why include realistic breaks in a study routine?", "options": ["To replace all study sessions", "To avoid returning to the material", "To make the routine manageable around sustained effort", "To guarantee perfect exam results"], "correctIndex": 2, "explanation": "A realistic routine considers both focused work and breaks instead of relying on endless effort."}, {"id": "q20", "lessonId": "reflecting-and-adapting", "prompt": "Which question best supports reviewing a study routine?", "options": ["Can I avoid reviewing the result?", "Did my notes look like everyone else's?", "Did I use the most fashionable technique?", "What could I recall or apply, and what should I change next time?"], "correctIndex": 3, "explanation": "Reviewing what you could recall and apply helps guide the next adjustment."}]$questions$::jsonb, md5(public.pap_assessment_source('learning-styles')::text));
    exception when others then
      raise notice 'Draft for learning-styles needs regeneration for this curriculum: %',sqlerrm;
    end;
  end if;
end $seed$;

do $seed$ begin
  if exists(select 1 from public.courses where id='nation-building') and not exists(select 1 from public.course_assessment_drafts where course_id='nation-building') then
    begin
      perform public.stage_course_assessment('nation-building', $questions$[{"id": "q1", "prompt": "Which action demonstrates responsible citizenship?", "options": ["Damaging shared facilities", "Helping care for a shared community space", "Preventing others from participating", "Ignoring shared responsibilities"], "correctIndex": 1, "explanation": "Taking care of shared spaces is one practical way to contribute to community life.", "lessonId": "rights-and-responsibilities"}, {"id": "q2", "prompt": "What is a useful first step when planning a community project?", "options": ["Promise results before planning", "Ignore the people affected", "Listen to residents and identify a real need", "Choose a solution without asking anyone"], "correctIndex": 2, "explanation": "Listening to residents helps identify a need and shape a project around those affected.", "lessonId": "identifying-community-needs"}, {"id": "q3", "prompt": "Which behaviour supports collaboration across differences?", "options": ["Excluding people with different views", "Assuming one person has every answer", "Refusing to listen", "Respecting others and looking for shared goals"], "correctIndex": 3, "explanation": "Respectful listening and shared goals help people with different experiences work together.", "lessonId": "working-across-differences"}, {"id": "q4", "prompt": "What does accountability mean in a group project?", "options": ["Taking responsibility for commitments and reporting progress honestly", "Hiding every setback", "Blaming others for all outcomes", "Taking credit for everyone's work"], "correctIndex": 0, "explanation": "Accountability includes owning your commitments and communicating honestly about progress.", "lessonId": "making-responsible-choices"}, {"id": "q5", "prompt": "How can a team review a small community initiative?", "options": ["Avoid speaking to participants", "Compare results with the goal and gather feedback", "Assume any activity was automatically successful", "Only count how many promises were made"], "correctIndex": 1, "explanation": "Comparing results with the goal and gathering feedback helps the team understand its impact.", "lessonId": "reflecting-on-your-contribution"}, {"id": "q6", "lessonId": "what-nation-building-means", "prompt": "Which example reflects nation building through everyday participation?", "options": ["Ignoring local needs", "Preventing community discussions", "Working with others to improve a shared service", "Leaving every shared problem to someone else"], "correctIndex": 2, "explanation": "Everyday cooperation on shared needs is one way people contribute to stronger communities."}, {"id": "q7", "lessonId": "rights-and-responsibilities", "prompt": "How are rights and responsibilities connected in community life?", "options": ["Having rights removes every responsibility", "Only leaders have responsibilities", "Responsibilities make participation impossible", "Enjoying rights can involve respecting the rights of others"], "correctIndex": 3, "explanation": "Community life involves both recognising your rights and respecting those of other people."}, {"id": "q8", "lessonId": "shared-values-and-belonging", "prompt": "Which action supports a sense of belonging?", "options": ["Welcoming participation while respecting differences", "Refusing to explain shared activities", "Excluding newcomers from every discussion", "Assuming only one background matters"], "correctIndex": 0, "explanation": "Inclusive participation and respect can help people feel part of a community."}, {"id": "q9", "lessonId": "leading-through-service", "prompt": "Which action best illustrates leadership through service?", "options": ["Taking every benefit for yourself", "Helping the group address a need and supporting others' contributions", "Refusing to do any shared work", "Demanding credit for work you did not do"], "correctIndex": 1, "explanation": "Service-oriented leadership focuses on a shared need and the contributions of others."}, {"id": "q10", "lessonId": "working-across-differences", "prompt": "A project team includes different backgrounds. What supports a shared plan?", "options": ["Avoid discussing the goals", "Exclude anyone with a different view", "Listen to different experiences and agree on common objectives", "Let only one person describe every need"], "correctIndex": 2, "explanation": "Listening across differences helps a team find common objectives without erasing its members' experiences."}, {"id": "q11", "lessonId": "making-responsible-choices", "prompt": "Before choosing a project action, what should the team consider?", "options": ["Only how impressive the announcement sounds", "Only who gets the most attention", "Whether consequences can be ignored", "Its likely effects on participants and the wider community"], "correctIndex": 3, "explanation": "Responsible decisions consider how an action may affect the people involved."}, {"id": "q12", "lessonId": "identifying-community-needs", "prompt": "Residents describe different problems in an area. How can a team decide which need to address?", "options": ["Gather information and compare urgency, impact, and available resources", "Pick without discussing any constraints", "Choose whichever idea was mentioned loudest", "Ignore everyone who disagrees"], "correctIndex": 0, "explanation": "Comparing information, priorities, and resources helps shape a realistic choice."}, {"id": "q13", "lessonId": "planning-a-small-initiative", "prompt": "What belongs in a practical project plan?", "options": ["Only an inspiring slogan", "A clear goal, tasks, responsibilities, resources, and timeline", "Promises with no tasks", "A list of benefits without any actions"], "correctIndex": 1, "explanation": "A practical plan connects the goal with what needs doing, by whom, and with which resources."}, {"id": "q14", "lessonId": "working-with-others", "prompt": "Why agree on roles before starting shared work?", "options": ["To guarantee there will be no problems", "To prevent anyone from asking questions", "To clarify responsibilities and reduce missed or duplicated tasks", "To stop all collaboration"], "correctIndex": 2, "explanation": "Clear roles help people coordinate their work and identify responsibilities."}, {"id": "q15", "lessonId": "reflecting-on-your-contribution", "prompt": "Which reflection helps improve a future initiative?", "options": ["How can we hide every setback?", "How can one person take all the credit?", "Can we avoid speaking to participants?", "What changed, what did we learn, and what should we adjust?"], "correctIndex": 3, "explanation": "Reflection uses outcomes and lessons to guide future decisions."}, {"id": "q16", "lessonId": "leading-through-service", "prompt": "A team member has useful experience but rarely speaks. What can a leader do?", "options": ["Invite their contribution without forcing them to speak", "Remove them from the team automatically", "Assume they have nothing to add", "Ignore their experience"], "correctIndex": 0, "explanation": "Making space for a contribution can help the team benefit from different experience."}, {"id": "q17", "lessonId": "planning-a-small-initiative", "prompt": "A project has fewer resources than expected. What is a realistic response?", "options": ["Promise more work without a plan", "Review the scope and prioritise achievable tasks", "Ignore the resource gap", "Hide the change from the team"], "correctIndex": 1, "explanation": "Adjusting scope connects the plan with the resources actually available."}, {"id": "q18", "lessonId": "working-with-others", "prompt": "What should a team do when a task is delayed?", "options": ["Blame someone without asking what happened", "Assume the delay has no effect", "Discuss the cause, update the timeline, and agree on the next action", "Avoid mentioning the delay"], "correctIndex": 2, "explanation": "Clear communication about a delay helps the team coordinate a response."}, {"id": "q19", "lessonId": "shared-values-and-belonging", "prompt": "Which value is demonstrated by reporting project expenses honestly?", "options": ["Exclusion", "Indifference", "Secrecy", "Integrity"], "correctIndex": 3, "explanation": "Honest reporting is an example of integrity in shared work."}, {"id": "q20", "lessonId": "reflecting-on-your-contribution", "prompt": "A cleanup goal was to clear four areas, and three were completed. Which report is accurate?", "options": ["Three of four areas were completed; one remains", "There is no way to describe the result", "All goals were fully met", "No work was completed"], "correctIndex": 0, "explanation": "An accurate report compares the actual result with the stated goal."}]$questions$::jsonb, md5(public.pap_assessment_source('nation-building')::text));
    exception when others then
      raise notice 'Draft for nation-building needs regeneration for this curriculum: %',sqlerrm;
    end;
  end if;
end $seed$;

